test('Set Up AI Chat keeps the previous config copy tracked when another config appears before its put-back from the empty path, and the next run puts that copy back', async (context) => {
  // Value: protects=a put-back that loses the race to another config never records the previous config's copy as handed over: the publish record stays in progress, so once that other config is gone the next run puts the copy back instead of leaving the config path empty; fails_when=the publish record is handed or gone, the other config or the copy changes, the copy goes over the other config, or the next run does not put it back; no_claim=a real sync tool (the config module is loaded with a link that deletes the new config once, and its openWithoutFollowing writes another config when the post-link read finds the empty path), a real save (that file is written by the test's injected racing program), and a first setup's old receipt
  // Arrange
  const { home, storage, configPath } = await arrange(context)
  const configText = '{"mcpServers":{"alpha":{"command":"a"}}}\n'
  await writeConfig(configPath, configText)
  const foreignText = '{"theme":"written meanwhile"}\n'
  const receiptPath = join(storage, 'devin-mcp', 'receipt.json')
  const pendingPath = join(storage, 'devin-mcp', 'pending.json')
  const { module: emptyAfterLink, emptied } =
    await loadWithEmptyConfigAfterLink(configPath, () => {
      writeFileSync(configPath, foreignText)
    })
  let displacedPath = ''

  // Act
  const error = await emptyAfterLink
    .writeManagedDevinMcpEntry(storage, ENTRY, home, {
      afterMoveAside: (path) => {
        displacedPath = path
      },
    })
    .then(
      () => undefined,
      (failure: unknown) => failure,
    )
  const recordAfter = existsSync(pendingPath)
    ? JSON.parse(readFileSync(pendingPath, 'utf8'))
    : 'absent'
  const isReceiptAfter = existsSync(receiptPath)
  // Moving the other config away is only how this test empties the config path, not the refusal's displayed guidance for a config that stands (merge the needed settings into it and re-run, which the next test follows). What this test proves is the recovery invariant: once the path stands empty again, the next run puts the tracked copy back on its own. It must still be the config written meanwhile.
  assert.equal(readFileSync(configPath, 'utf8'), foreignText)
  renameSync(configPath, join(dirname(configPath), 'other-config.json'))
  const next = await refreshManagedDevinMcpEntry(storage, ENTRY, home)

  // Assert
  assert.equal(
    error instanceof Error ? error.message : error,
    `Codebook found a copy of your config that Codebook kept at ${displacedPath} and could not settle in Devin Desktop's MCP config at ${configPath} and left that file untouched; look at both files before you use either: if no file stands at the config path, move that copy back there; otherwise compare the two, move only the settings you need from that copy into the config, never that copy over the config, and afterwards delete that copy or move it elsewhere, then run Codebook: Set Up AI Chat again.`,
  )
  assert.equal(emptied.count, 1)
  assert.equal(recordAfter.phase, undefined)
  assert.equal(isReceiptAfter, false)
  assert.equal(next.status, 'not-managed')
  assert.equal(readFileSync(configPath, 'utf8'), configText)
  assert.equal(existsSync(displacedPath), false)
})

test('Set Up AI Chat installs its entry beside the merged servers when the learner follows the refusal’s guidance: only the needed settings moved from the copy into the config that stands, never the copy over it, and the copy moved aside', async (context) => {
  // Value: protects=the recovery path the could-not-settle refusal displays for a config that stands being a working one: the learner compares the copy with the config, moves only the settings they need from that copy into the config, which stays in place, moves the copy elsewhere, and the next run settles the interrupted publish record on its own and installs the entry beside every server the merged config holds, so following the displayed guidance loses no setting of either file and keeps the copy where the learner put it; fails_when=the re-run refuses or answers anything but installed, a server of the copy or of the config written meanwhile is missing or changed in the config that stands, the copy the learner moved aside is gone or changed, a private file stays beside the config, or no receipt of the new setup stands; no_claim=a real sync tool (the config module is loaded with a link that deletes the new config once, and its openWithoutFollowing writes another config when the post-link read finds the empty path), a real save (that file is written by the test's injected racing program), and the learner's own editing program (the test writes the merged bytes itself)
  // Arrange
  const { home, storage, configPath } = await arrange(context)
  const configText = '{"mcpServers":{"alpha":{"command":"a"}}}\n'
  await writeConfig(configPath, configText)
  const foreignText = '{"mcpServers":{"beta":{"command":"b"}}}\n'
  const pendingPath = join(storage, 'devin-mcp', 'pending.json')
  const { module: emptyAfterLink, emptied } =
    await loadWithEmptyConfigAfterLink(configPath, () => {
      writeFileSync(configPath, foreignText)
    })
  let displacedPath = ''

  // Act
  const error = await emptyAfterLink
    .writeManagedDevinMcpEntry(storage, ENTRY, home, {
      afterMoveAside: (path) => {
        displacedPath = path
      },
    })
    .then(
      () => undefined,
      (failure: unknown) => failure,
    )
  // The learner follows the refusal's displayed guidance: they compare the copy with the config that stands and move only the settings they need — the alpha server the copy alone holds — into that config, which stays in place, never the copy over the config.
  const copyServers = JSON.parse(readFileSync(displacedPath, 'utf8'))
    .mcpServers as object
  const standingConfig = JSON.parse(readFileSync(configPath, 'utf8')) as {
    mcpServers?: object
  }
  writeFileSync(
    configPath,
    `${JSON.stringify({
      ...standingConfig,
      mcpServers: { ...standingConfig.mcpServers, ...copyServers },
    })}\n`,
  )
  // ... and afterwards move that copy elsewhere, then run Codebook: Set Up AI Chat again.
  const copyAsidePath = join(home, 'previous-config-copy.json')
  renameSync(displacedPath, copyAsidePath)
  const next = await writeManagedDevinMcpEntry(storage, ENTRY, home)

  // Assert
  assert.equal(
    error instanceof Error ? error.message : error,
    `Codebook found a copy of your config that Codebook kept at ${displacedPath} and could not settle in Devin Desktop's MCP config at ${configPath} and left that file untouched; look at both files before you use either: if no file stands at the config path, move that copy back there; otherwise compare the two, move only the settings you need from that copy into the config, never that copy over the config, and afterwards delete that copy or move it elsewhere, then run Codebook: Set Up AI Chat again.`,
  )
  assert.equal(emptied.count, 1)
  assert.equal(next.status, 'installed')
  // Every server of both files stands beside the new entry: beta of the config written meanwhile, alpha of the copy, codebook of this run.
  assert.deepEqual(JSON.parse(readFileSync(configPath, 'utf8')), {
    mcpServers: {
      beta: { command: 'b' },
      alpha: { command: 'a' },
      codebook: ENTRY,
    },
  })
  // The copy the learner moved aside is never touched, and no private file or record stays.
  assert.equal(readFileSync(copyAsidePath, 'utf8'), configText)
  assert.equal(existsSync(displacedPath), false)
  assert.deepEqual(await leftoversBeside(configPath), [])
  assert.equal(existsSync(pendingPath), false)
  assert.equal(
    (await readRecordFile(storage, 'receipt.json')).generation,
    next.generation,
  )
})

/**
 * Loads the config module with an `openWithoutFollowing` that fails the first `failures` opens of the config that reach the file the publish link put there, with EMFILE, the way a process out of file handles fails the read of the config right after its link; every other open is the real one. The link's landing is told by the inode the staged read right before it lends: an open of the config whose name shows that inode is a read after the link, and one before it is never failed, so a config read before the publish can never consume a failure meant for the retry path.
 * @param configPath - The config file.
 * @param failures - How many opens of the published config fail from then on.
 * @returns The config module; `failed.count` how many opens failed and `failed.atOpens` at which open after the link each did (the first post-publish read is 1, its retry 2); `unpublished.count` how many opens of the config came after the staged read but before their name showed the staged inode, which an honest publish never does and the tests assert.
 * @example
 * const { module, failed, unpublished } = await loadWithFailingConfigReadsAfterLink(configPath, 1)
 */
async function loadWithFailingConfigReadsAfterLink(
  configPath: string,
  failures: number,
): Promise<{
  module: typeof DevinMcpConfigModule
  failed: { count: number; atOpens: number[] }
  unpublished: { count: number }
}> {
  const failed: { count: number; atOpens: number[] } = { count: 0, atOpens: [] }
  const unpublished = { count: 0 }
  let stagedIno: bigint | undefined
  let opensAfterLink = 0
  const module = await loadWithWrappedOpen(async (path, openReal) => {
    // The setup's last read of its staged config comes right before its link, through this very handle: the inode it reads is the one the link then puts at the config name.
    if (
      basename(path).startsWith('mcp_config.json.') &&
      path.endsWith('.tmp')
    ) {
      const file = await openReal()
      stagedIno = (await file.stat({ bigint: true })).ino
      return file
    }
    if (path !== configPath) return openReal()
    const shownIno = lstatSync(configPath, {
      bigint: true,
      throwIfNoEntry: false,
    })?.ino
    // A read after the link only once the config name reaches the very file the staged read lent its inode: before the link the name is empty or shows the older config.
    if (stagedIno === undefined || shownIno !== stagedIno) {
      if (stagedIno !== undefined) unpublished.count += 1
      return openReal()
    }
    opensAfterLink += 1
    if (failed.count < failures) {
      failed.count += 1
      failed.atOpens.push(opensAfterLink)
      throw Object.assign(new Error('too many open files'), { code: 'EMFILE' })
    }
    return openReal()
  })
  return { module, failed, unpublished }
}

/**
 * Gives the refusal of a setup that put its new config in place but could not read that config again right afterwards ({@link writeManagedDevinMcpEntry}).
 * @param configPath - The config file.
 * @param pendingPath - The setup's record of its change.
 * @returns The refusal's message, without the sentence about a moved-aside copy.
 * @example
 * unreadAfterLinkRefusalText(configPath, pendingPath) // => 'Codebook put its new version of Devin Desktop's MCP config in place at … but could not read that file again right afterwards …'
 */
function unreadAfterLinkRefusalText(
  configPath: string,
  pendingPath: string,
): string {
  return `Codebook put its new version of Devin Desktop's MCP config in place at ${configPath} but could not read that file again right afterwards (for example for lack of file handles), so it did not record that change as finished and went no further; its record of that change at ${pendingPath} stays, and the next run reads it first; make that config readable by you if it is not, then run Codebook: Set Up AI Chat again.`
}

test('A setup that cannot read its new config again right after putting it in place for lack of file handles never hands your previous config over or blames another program, and the next run finishes the setup', async (context) => {
  // Value: protects=a read of the config that fails right after the link (EMFILE, EIO) is told apart from another file or other bytes there: it is tried once more, and when it fails again the setup refuses with the could-not-read sentence, keeps its record of the change as it stood before the link and the moved-aside copy as one that record still tracks, writes no receipt and hands nothing over, so the next run settles that change on its own checks and the setup then stands (Cycle 0149 ship review, pass 2 red team on task 51's read after the link); fails_when=the refusal is the changed-file one or names the copy as handed over, the copy is gone or changed, the record is handed or gone, a receipt stands, the reads after the link are not two, or the next run does not end installed with the old servers and the entry; no_claim=a real EMFILE (the config module is loaded with an openWithoutFollowing that fails every open of the config that reaches the file the publish link put there with EMFILE, told by the inode the staged read right before it lends), the next run's steps in between (it takes the first setup's entry back out and sets it up again, or keeps it; only its end is asserted)
  // Arrange
  const { home, storage, configPath } = await arrange(context)
  const configText = '{"mcpServers":{"alpha":{"command":"a"}}}\n'
  await writeConfig(configPath, configText)
  const receiptPath = join(storage, 'devin-mcp', 'receipt.json')
  const pendingPath = join(storage, 'devin-mcp', 'pending.json')
  const {
    module: failingRead,
    failed,
    unpublished,
  } = await loadWithFailingConfigReadsAfterLink(configPath, Infinity)
  let displacedPath = ''

  // Act
  const error = await failingRead
    .writeManagedDevinMcpEntry(storage, ENTRY, home, {
      afterMoveAside: (path) => {
        displacedPath = path
      },
    })
    .then(
      () => undefined,
      (failure: unknown) => failure,
    )
  // A name the setup left empty reads as 'absent', so the assertions below name it.
  const copyAfter = existsSync(displacedPath)
    ? readFileSync(displacedPath, 'utf8')
    : 'absent'
  const recordAfter = existsSync(pendingPath)
    ? JSON.parse(readFileSync(pendingPath, 'utf8'))
    : 'absent'
  const isReceiptAfter = existsSync(receiptPath)
  const next = await writeManagedDevinMcpEntry(storage, ENTRY, home)

  // Assert
  assert.equal(
    error instanceof Error ? error.message : error,
    `${unreadAfterLinkRefusalText(configPath, pendingPath)} Codebook kept a private copy of your previous Devin MCP config at ${displacedPath} (it holds the settings of your other servers), but Codebook still tracks that copy, so a later run of Codebook deletes it while it still holds exactly your previous config; copy it elsewhere to keep it.`,
  )
  assert.equal(failed.count, 2)
  // Both failures fired at reads after the link: the first read and its retry, never a read before the publish.
  assert.deepEqual(failed.atOpens, [1, 2])
  assert.equal(unpublished.count, 0)
  assert.equal(copyAfter, configText)
  assert.equal(recordAfter.keptName, basename(displacedPath))
  assert.equal(recordAfter.phase, undefined)
  assert.equal(isReceiptAfter, false)
  assert.equal(next.status, 'installed')
  assert.deepEqual(JSON.parse(readFileSync(configPath, 'utf8')), {
    mcpServers: { alpha: { command: 'a' }, codebook: ENTRY },
  })
  assert.deepEqual(await leftoversBeside(configPath), [])
})

