test("A first setup's take-back that stops inside its first rollback-record write where Codebook's storage folder cannot give a file a second name leaves no empty rollback record, so the next refresh takes the entry out instead of refusing every run", async (context) => {
  // Value: protects=on storage without hard links a take-back's first rollback record appears at its name only complete (a rename of its flushed staged file at a name a synchronous look found empty), so a stop inside that write never leaves a record every run refuses (Cycle 0149 task 5); fails_when=the run never stopped at the rename that publishes that record, the entry is gone before the next refresh, anything stands at pending.json.rollback after the setup, the next refresh refuses or answers anything but not-managed, or the entry, a record, a receipt or a pending.json.rollback name stays; no_claim=a real process end or exFAT (the config module is loaded with a link that refuses every name in the storage folder with ENOTSUP, an open that ends the run right after an exclusive create of the rollback record's own name, and a rename that ends it right before publishing at that name), a file another program puts at that name between the last look and the rename (stated residual on such storage), the setup's own pending.json (same step)
  // Arrange
  const { home, storage, configPath } = await arrange(context)
  await writeConfig(configPath, '{"mcpServers":{"alpha":{"command":"a"}}}\n')
  const recordsPath = join(storage, 'devin-mcp')
  const receiptPath = join(recordsPath, 'receipt.json')
  const pendingPath = join(recordsPath, 'pending.json')
  const journalPath = `${pendingPath}.rollback`
  let hasStoppedAtRename = false
  const endingInsideFirstWrite = await loadModule<typeof DevinMcpConfigModule>(
    resolve(__dirname, '../devinMcpConfig.js'),
    {
      'node:fs/promises': {
        link: async (from: string, to: string) => {
          // The storage folder's file system gives no file a second name; the config's folder does.
          if (dirname(to) === recordsPath)
            throw Object.assign(
              new Error(`ENOTSUP: operation not supported, link '${from}'`),
              { code: 'ENOTSUP' },
            )
          return link(from, to)
        },
        lstat,
        mkdir,
        open: async (...args: Parameters<typeof open>) => {
          // The process ends right after an exclusive create of the rollback record's own name, before any byte is in it.
          if (args[0] === journalPath && args[1] === 'wx') {
            await (await open(...args)).close()
            throw new Error('process ended')
          }
          return open(...args)
        },
        rename: async (from: string, to: string) => {
          // The process ends right before the rollback record's bytes are published at its name.
          if (to === journalPath) {
            hasStoppedAtRename = true
            throw new Error('process ended')
          }
          return rename(from, to)
        },
        rm,
        unlink,
      },
    },
    { Error, TextDecoder },
  )
  await endingInsideFirstWrite
    .writeManagedDevinMcpEntry(storage, ENTRY, home, {
      afterPublish: () => mkdirSync(receiptPath, { recursive: true }),
    })
    .catch(() => undefined)
  // A name the setup left empty reads as 'absent', so the assertion below names what stands there.
  const journalAfterSetup = existsSync(journalPath)
    ? `${statSync(journalPath).size} bytes`
    : 'absent'
  const configAfterSetup = JSON.parse(readFileSync(configPath, 'utf8'))
  rmSync(receiptPath, { recursive: true })

  // Act
  const refresh = await refreshManagedDevinMcpEntry(storage, ENTRY, home)

  // Assert
  assert.equal(hasStoppedAtRename, true)
  // The take-back stopped before it took the entry out: the next refresh does.
  assert.deepEqual(configAfterSetup, {
    mcpServers: { alpha: { command: 'a' }, codebook: ENTRY },
  })
  assert.equal(journalAfterSetup, 'absent')
  assert.equal(refresh.status, 'not-managed')
  assert.deepEqual(JSON.parse(readFileSync(configPath, 'utf8')), {
    mcpServers: { alpha: { command: 'a' } },
  })
  assert.equal(existsSync(pendingPath), false)
  assert.equal(existsSync(receiptPath), false)
  assert.deepEqual(
    readdirSync(recordsPath).filter((name) =>
      name.startsWith('pending.json.rollback'),
    ),
    [],
  )
})

test("A setup record whose rewrite cannot be published where Codebook's storage folder cannot give a file a second name goes back to its name in that run, so the next refresh reads it instead of refusing every run", async (context) => {
  // Value: protects=on storage without hard links a tracked record that a rewrite moved to its dropping name goes back to its emptied name in that run when the new bytes cannot be published, by a rename right after a synchronous look finds that name empty, so no later setup, refresh or removal refuses at its start (Cycle 0149 task 17); fails_when=the failure is not injected, the dropping name stays after the setup, pending.json does not hold the record the setup's claim wrote (complete, not yet completed) after the setup, or the next refresh answers anything but current or leaves a record or its dropping name; no_claim=a real full disk or exFAT (the config module is loaded with a link that refuses every name in the storage folder with ENOTSUP and, once the setup's completed record is written, fails the first publication of that rewrite with ENOSPC: an exclusive create of pending.json before Cycle 0149 task 18, a rename of its staged file there since), a file another program puts at the record's name between that last look and the rename (stated residual on such storage)
  // Arrange
  const { home, storage, configPath } = await arrange(context)
  await writeConfig(configPath, '{"mcpServers":{"alpha":{"command":"a"}}}\n')
  const recordsPath = join(storage, 'devin-mcp')
  const pendingPath = join(recordsPath, 'pending.json')
  const droppingPath = `${pendingPath}.codebook-dropping`
  let isArmed = false
  let hasFailedPublish = false
  const fullDisk = (): Error =>
    Object.assign(new Error('ENOSPC: no space left on device'), {
      code: 'ENOSPC',
    })
  const withoutStorageLinks = await loadModule<typeof DevinMcpConfigModule>(
    resolve(__dirname, '../devinMcpConfig.js'),
    {
      'node:fs/promises': {
        link: async (from: string, to: string) => {
          // The storage folder's file system gives no file a second name; the config's folder does.
          if (dirname(to) === recordsPath)
            throw Object.assign(
              new Error(`ENOTSUP: operation not supported, link '${from}'`),
              { code: 'ENOTSUP' },
            )
          return link(from, to)
        },
        lstat,
        mkdir,
        open: async (...args: Parameters<typeof open>) => {
          // The disk is full at the rewrite's exclusive create of the setup record's own name.
          if (
            isArmed &&
            !hasFailedPublish &&
            args[0] === pendingPath &&
            args[1] === 'wx'
          ) {
            hasFailedPublish = true
            throw fullDisk()
          }
          return open(...args)
        },
        rename: async (from: string, to: string) => {
          // The disk is full at the rewrite's rename of its staged file to the setup record's own name.
          if (
            isArmed &&
            !hasFailedPublish &&
            to === pendingPath &&
            from.endsWith('.tmp')
          ) {
            hasFailedPublish = true
            throw fullDisk()
          }
          return rename(from, to)
        },
        rm,
        unlink,
      },
    },
    { Error, TextDecoder },
  )
  await withoutStorageLinks.writeManagedDevinMcpEntry(storage, ENTRY, home, {
    beforeRecordWrite: ({ path, record }) => {
      // Only the setup's completed record, the first rewrite of the record its claim wrote.
      if (path !== pendingPath) return
      if (JSON.parse(JSON.stringify(record)).phase === 'completed')
        isArmed = true
    },
  })
  const isDroppingAfterSetup = existsSync(droppingPath)
  // The record the claim wrote, back at its name, or 'absent', so the assertions below name what stands there.
  const recordAfterSetup = existsSync(pendingPath)
    ? JSON.parse(readFileSync(pendingPath, 'utf8'))
    : 'absent'

  // Act
  const refresh = await withoutStorageLinks.refreshManagedDevinMcpEntry(
    storage,
    ENTRY,
    home,
  )

  // Assert
  assert.equal(hasFailedPublish, true)
  assert.equal(isDroppingAfterSetup, false)
  assert.equal(recordAfterSetup.targetPath, configPath)
  assert.equal('phase' in recordAfterSetup, false)
  assert.equal(refresh.status, 'current')
  assert.deepEqual(JSON.parse(readFileSync(configPath, 'utf8')), {
    mcpServers: { alpha: { command: 'a' }, codebook: ENTRY },
  })
  assert.equal(existsSync(pendingPath), false)
  assert.equal(existsSync(droppingPath), false)
})

