test("A refresh that would record an entry an interrupted setup published never writes that record over Codebook's record of the entry in another home folder's config, and names that record", async (context) => {
  // Value: protects=the adoption of an entry an interrupted setup published never writes over a valid record at receipt.json that names another config path, refuses, names that record and the config it names, and keeps the interrupted setup's record, so the refresh after that record was moved away adopts the entry (Cycle 0149 task 49); fails_when=the refresh resolves or says anything but the other-config sentence, receipt.json, pending.json or the config changes, or the refresh after the record was moved away answers anything but current with a receipt of the interrupted setup's generation; no_claim=a real copy of Codebook's storage folder made under another home folder (the test writes a valid record whose targetPath names a config under a sibling home folder) and a real interrupted older build (the test writes its setup record, without a first-setup mark, beside the config that holds its entry)
  // Arrange
  const { home, storage, configPath } = await arrange(context)
  await writeConfig(
    configPath,
    `${JSON.stringify({ mcpServers: { alpha: { command: 'a' }, codebook: ENTRY } })}\n`,
  )
  const configText = readFileSync(configPath, 'utf8')
  const pendingPath = join(storage, 'devin-mcp', 'pending.json')
  const { receiptPath, otherConfigPath, otherRecordText } =
    await writeOtherHomeRecord(storage, home)
  const interruptedRecordText = JSON.stringify({
    targetPath: configPath,
    entrySha256: ENTRY_HASH,
    createdFile: false,
    generation: 'c0ffee00-0000-4000-8000-000000004903',
    stagedIno: (await stat(configPath)).ino,
  })
  await writeFile(pendingPath, interruptedRecordText)
  const movedAwayPath = join(home, 'other-home-record.json')

  // Act
  const refreshOutcome = await refreshManagedDevinMcpEntry(
    storage,
    ENTRY,
    home,
  ).then(
    ({ status }) => `resolved: ${status}`,
    (error: Error) => error.message,
  )
  const receiptAfterRefresh = readFileSync(receiptPath, 'utf8')
  // A record the refresh ended reads as 'absent', so the assertion names it.
  const pendingAfterRefresh = existsSync(pendingPath)
    ? readFileSync(pendingPath, 'utf8')
    : 'absent'
  const configAfterRefresh = readFileSync(configPath, 'utf8')
  // The way out the refusal names: that record goes to another folder.
  renameSync(receiptPath, movedAwayPath)
  const next = await refreshManagedDevinMcpEntry(storage, ENTRY, home)

  // Assert
  assert.equal(
    refreshOutcome,
    `Codebook found at ${receiptPath}, where it keeps its record of the "codebook" entry in Devin Desktop's MCP config at ${configPath}, its record of that entry in the MCP config at ${otherConfigPath} instead (Codebook's storage folder may have been copied from another home folder), so it did not write over or delete that record, left it as it is and went no further; if you no longer use ${otherConfigPath}, move that record to another folder, then run Codebook: Set Up AI Chat again.`,
  )
  assert.equal(receiptAfterRefresh, otherRecordText)
  assert.equal(pendingAfterRefresh, interruptedRecordText)
  assert.equal(configAfterRefresh, configText)
  assert.equal(next.status, 'current')
  assert.equal(
    (await readRecordFile(storage, 'receipt.json')).generation,
    'c0ffee00-0000-4000-8000-000000004903',
  )
})

test("A removal whose take-back of a cut-short first setup took the entry out keeps Codebook's record of the entry in another home folder's config, says so, and still answers removed", async (context) => {
  // Value: protects=a removal whose own run took a cut-short first setup back never deletes a valid record at receipt.json that names another config path, and its notice names that record and the config it names, while the removal still reports the entry it took back (Cycle 0149 task 49); fails_when=the removal answers anything but removed with the other-config kept sentence, receipt.json is gone or changes, or the config keeps the entry or loses the other server; no_claim=a real copy of Codebook's storage folder made under another home folder (the test writes a valid record whose targetPath names a config under a sibling home folder after the first setup was cut short), a real stop of the first setup (seam.afterPublish blocks its receipt with a folder and seam.afterMoveAside ends its rollback)
  // Arrange
  const { home, storage, configPath } = await arrange(context)
  await writeConfig(configPath, '{"mcpServers":{"alpha":{"command":"a"}}}\n')
  const blockedReceiptPath = join(storage, 'devin-mcp', 'receipt.json')
  let moveAsideCount = 0
  await writeManagedDevinMcpEntry(storage, ENTRY, home, {
    afterPublish: () => mkdirSync(blockedReceiptPath, { recursive: true }),
    afterMoveAside: () => {
      moveAsideCount += 1
      if (moveAsideCount === 2) throw new Error('process ended')
    },
  }).catch(() => undefined)
  rmSync(blockedReceiptPath, { recursive: true })
  const { receiptPath, otherConfigPath, otherRecordText } =
    await writeOtherHomeRecord(storage, home)

  // Act
  const result = await removeManagedDevinMcpEntry(storage, home)

  // Assert
  assert.deepEqual(result, {
    status: 'removed',
    path: configPath,
    cleanupFailure: `Codebook left the file at ${receiptPath} as it is, because it holds its record of the "codebook" entry in the MCP config at ${otherConfigPath}, not in this one (Codebook's storage folder may have been copied from another home folder); if you no longer use ${otherConfigPath}, move that file to another folder.`,
  })
  // A record the removal deleted reads as 'absent', so the assertion names it.
  assert.equal(
    existsSync(receiptPath) ? readFileSync(receiptPath, 'utf8') : 'absent',
    otherRecordText,
  )
  assert.deepEqual(JSON.parse(readFileSync(configPath, 'utf8')), {
    mcpServers: { alpha: { command: 'a' } },
  })
})

/**
 * Loads the config module with a link, a rename and an unlink that, the first time one is about to change `receipt.json` (an unlink of that name, or a link or rename from or to it; a move to its private name links first since Cycle 0149 task 37), first call `beforeChange`, so a test can act right after the module's last look at that name and before the step that moves, replaces or deletes what stands there.
 * @param receiptPath - The receipt's path.
 * @param beforeChange - Called once, right before that link, rename or unlink runs.
 * @returns The config module.
 * @example
 * const module = await loadWithBeforeReceiptChange(receiptPath, () => swapFile(receiptPath, restoredText))
 */
function loadWithBeforeReceiptChange(
  receiptPath: string,
  beforeChange: () => void,
): Promise<typeof DevinMcpConfigModule> {
  let hasChanged = false
  const changeOnce = (paths: string[]): void => {
    if (hasChanged || !paths.includes(receiptPath)) return
    hasChanged = true
    beforeChange()
  }
  return loadModule<typeof DevinMcpConfigModule>(
    resolve(__dirname, '../devinMcpConfig.js'),
    {
      'node:fs/promises': {
        link: async (from: string, to: string) => {
          changeOnce([from, to])
          await link(from, to)
        },
        lstat,
        mkdir,
        open,
        rename: async (from: string, to: string) => {
          changeOnce([from, to])
          await rename(from, to)
        },
        rm,
        unlink: async (path: string) => {
          changeOnce([path])
          await unlink(path)
        },
      },
    },
    { Error, TextDecoder },
  )
}

test('A removal never deletes a record a backup renames over receipt.json right after the removal last looked at it, says so, and the next removal settles that record', async (context) => {
  // Value: protects=a removal deletes Codebook's record of the entry only once that record moved to its private name and proved there to be the version the removal read, so a record a backup renames over receipt.json after the removal's last look moves with it, goes back to receipt.json and stays, the notice says so, and the next removal settles that record (Cycle 0149 task 50); fails_when=receipt.json is gone or holds anything but the restored record after the removal, a private name of it stays, the removal answers anything but removed with the kept-record sentence, the config keeps the entry or loses the other server, or the next removal answers anything but not-managed or leaves a record; no_claim=a real backup tool (the config module is loaded with a rename and an unlink that, once, right before the first one that changes receipt.json, rename an older record of this config over that name), a swap at the record's private name (a name only Codebook uses)
  // Arrange
  const { home, storage, configPath } = await arrange(context)
  await writeConfig(configPath, '{"mcpServers":{"alpha":{"command":"a"}}}\n')
  await writeManagedDevinMcpEntry(storage, ENTRY, home)
  const receiptPath = join(storage, 'devin-mcp', 'receipt.json')
  const restoredText = JSON.stringify({
    ...JSON.parse(readFileSync(receiptPath, 'utf8')),
    generation: 'c0ffee00-0000-4000-8000-000000005001',
  })
  const restoring = await loadWithBeforeReceiptChange(receiptPath, () =>
    // A backup renames an older record over receipt.json right after the removal's last look at it.
    swapFile(receiptPath, restoredText),
  )

  // Act
  // The loaded module's result comes from another realm; its own fields are compared.
  const result = {
    ...(await restoring.removeManagedDevinMcpEntry(storage, home)),
  }
  // A record the removal deleted reads as 'absent', so the assertion names it.
  const receiptAfterRemoval = existsSync(receiptPath)
    ? readFileSync(receiptPath, 'utf8')
    : 'absent'
  const recordsAfterRemoval = await recordsIn(storage)
  const next = await removeManagedDevinMcpEntry(storage, home)

  // Assert
  assert.deepEqual(result, {
    status: 'removed',
    path: configPath,
    cleanupFailure: `Codebook left the file at ${receiptPath} as it is, because it could not confirm that it was still the record of that entry Codebook had read there (a backup or sync tool may have put a record back there); the next run reads it again.`,
  })
  assert.equal(receiptAfterRemoval, restoredText)
  assert.deepEqual(recordsAfterRemoval, ['receipt.json'])
  assert.deepEqual(JSON.parse(readFileSync(configPath, 'utf8')), {
    mcpServers: { alpha: { command: 'a' } },
  })
  assert.deepEqual(next, { status: 'not-managed', path: configPath })
  assert.deepEqual(await recordsIn(storage), [])
})

test('A removal whose config a backup puts back with the entry right after the reduced config was confirmed keeps its record and refuses, and the next removal takes the entry out', async (context) => {
  // Value: protects=a removal deletes Codebook's record of the entry only while the entry it just took out is still out of the config when the delete is decided, so a backup that restores the config with the entry after the removal's publish never leaves that entry without the record that owns it, the removal refuses instead of reporting a success that did not last, and the next removal takes the entry out (Cycle 0149 task 73); fails_when=the removal resolves or refuses with another sentence, receipt.json is gone or changed after it, the config does not hold the entry again, or the next removal answers anything but removed; no_claim=a real backup tool (seam.afterPublish writes the config with its entry back in place once, right after the reduced config is confirmed), a restore in the instant after the last synchronous look before the record's unlink, which no Node primitive can close
  // Arrange
  const { home, storage, configPath } = await arrange(context)
  await writeConfig(configPath, '{"mcpServers":{"alpha":{"command":"a"}}}\n')
  await writeManagedDevinMcpEntry(storage, ENTRY, home)
  const receiptPath = join(storage, 'devin-mcp', 'receipt.json')
  const configWithEntry = readFileSync(configPath, 'utf8')
  const receiptText = readFileSync(receiptPath, 'utf8')
  let hasRestored = false

  // Act
  const removalOutcome = await removeManagedDevinMcpEntry(storage, home, {
    afterPublish: () => {
      if (hasRestored) return
      hasRestored = true
      // A backup puts the config with the entry back right after the reduced config was confirmed.
      swapFile(configPath, configWithEntry)
    },
  }).then(
    (result) => `resolved: ${result.status}`,
    (error: Error) => error.message,
  )
  // The refused removal leaves every file as the backup's restore made it, told before the next removal takes the entry out (which rewrites the config and deletes the record).
  const configAfterFirst = readFileSync(configPath, 'utf8')
  const receiptAfterFirst = readFileSync(receiptPath, 'utf8')
  const next = await removeManagedDevinMcpEntry(storage, home)

  // Assert
  assert.equal(hasRestored, true)
  assert.equal(
    removalOutcome,
    `Codebook took the "codebook" entry out of Devin Desktop's MCP config at ${configPath}, but before it could delete its own record of that entry, that config changed again (a backup or sync tool may have put an earlier config, with the entry, back), so it could not confirm the entry stayed out, left that record and that config as they are and went no further; then run Codebook: Remove Devin Desktop Setup again.`,
  )
  assert.equal(configAfterFirst, configWithEntry)
  assert.equal(receiptAfterFirst, receiptText)
  assert.equal(next.status, 'removed')
  assert.equal(existsSync(receiptPath), false)
})

test('A removal retry whose config a backup puts back with the entry before the record of the entry is deleted keeps that record and refuses, and the next removal takes the entry out', async (context) => {
  // Value: protects=a removal retry deletes Codebook's record of the entry only while the entry the earlier removal took out is still out of the config when the delete is decided, so a backup that restores only the config, with the entry, after the retry read that record never leaves the entry without the record that owns it, the retry refuses instead of reporting a removal that did not last, and the next removal takes the entry out (Cycle 0149 task 73's retry path); fails_when=the retry resolves or refuses with another sentence, receipt.json is gone or changed after it, the config does not hold the entry again, or the next removal answers anything but removed; no_claim=a real backup tool (seam.afterLeftoverCheck writes the config with its entry back in place once, at the retry's last look at pending.json before the retry ends the earlier removal's record, after the retry read its record of the entry), a restore in the instant after the last synchronous look before the record's unlink, which no Node primitive can close
  // Arrange
  const { home, storage, configPath } = await arrange(context)
  await writeConfig(configPath, '{"mcpServers":{"alpha":{"command":"a"}}}\n')
  await writeManagedDevinMcpEntry(storage, ENTRY, home)
  const configWithEntry = readFileSync(configPath, 'utf8')
  const receiptPath = join(storage, 'devin-mcp', 'receipt.json')
  const pendingPath = join(storage, 'devin-mcp', 'pending.json')
  const receiptText = readFileSync(receiptPath, 'utf8')
  let pendingBytes = ''
  await assert.rejects(
    removeManagedDevinMcpEntry(storage, home, {
      afterPublish: () => {
        pendingBytes = readFileSync(pendingPath, 'utf8')
        rmSync(pendingPath, { force: true })
        mkdirSync(pendingPath)
      },
    }),
    /could not write its own record/,
  )
  // Only the steps the refusal displays: the folder moves to another folder, and the record a backup held goes back.
  renameSync(pendingPath, join(home, 'folder-moved-aside'))
  writeFileSync(pendingPath, pendingBytes)
  const configBackupPath = join(home, 'mcp_config-from-backup.json')
  let hasReadReceipt = false
  let hasRestored = false

  // Act
  const retryOutcome = await removeManagedDevinMcpEntry(storage, home, {
    afterStat: (path) => {
      if (path === receiptPath) hasReadReceipt = true
    },
    afterLeftoverCheck: (path) => {
      // Recovery looks at pending.json before the receipt's read too; only the look after that read ends the earlier removal's record.
      if (path !== pendingPath || !hasReadReceipt || hasRestored) return
      hasRestored = true
      // A backup puts the config with the entry back after the retry inspected both names.
      writeFileSync(configBackupPath, configWithEntry)
      renameSync(configBackupPath, configPath)
    },
  }).then(
    (result) => `resolved: ${result.status}`,
    (error: Error) => error.message,
  )
  // The refused retry leaves every file as the backup's restore made it, told before the next removal takes the entry out (which rewrites the config and deletes the record).
  const configAfterRetry = readFileSync(configPath, 'utf8')
  const receiptAfterRetry = readFileSync(receiptPath, 'utf8')
  const next = await removeManagedDevinMcpEntry(storage, home)

  // Assert
  assert.equal(hasRestored, true)
  assert.equal(
    retryOutcome,
    `Codebook took the "codebook" entry out of Devin Desktop's MCP config at ${configPath}, but before it could delete its own record of that entry, that config changed again (a backup or sync tool may have put an earlier config, with the entry, back), so it could not confirm the entry stayed out, left that record and that config as they are and went no further; then run Codebook: Remove Devin Desktop Setup again.`,
  )
  assert.equal(configAfterRetry, configWithEntry)
  assert.equal(receiptAfterRetry, receiptText)
  assert.equal(next.status, 'removed')
  assert.equal(existsSync(receiptPath), false)
})

